export function setRigVertexWeight(data,index,bone,value){const vertex=data.vertices[index];if(!vertex||!data.bones.some(b=>b.id===bone)||!finite(value,0,1))throw Error('리그 정점 가중치 오류');const others=vertex.weights.filter(w=>w.bone!==bone).sort((a,b)=>b.weight-a.weight||(a.bone<b.bone?-1:1)).slice(0,value>0?3:4),sum=others.reduce((s,w)=>s+w.weight,0);if(!sum&&value<1){const fallback=data.bones.find(b=>b.id!==bone);if(fallback)others.push({bone:fallback.id,weight:1});}const total=others.reduce((s,w)=>s+w.weight,0);vertex.weights=normalizeRigWeights([{bone,weight:value},...others.map(w=>({bone:w.bone,weight:total?w.weight/total*(1-value):0}))],bone);}
